import java.awt.*;
import java.io.*;
import java.lang.reflect.Array;
import java.math.BigInteger;
import java.util.*;
import java.util.Random;
import java.util.StringTokenizer;

public class Main {

    String fileName = "";
    int[][] steps = {{0,1}, {1, 0}};
    int INF = Integer.MAX_VALUE / 10 - 123123;


    static int checkBit(int mask, int bit) {
        return (mask >> bit) & 1;
    }

    class Pair{
        int a, b;

        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public boolean equals(Object obj) {
            Pair o = (Pair) (obj);
            return this.a == o.a && this.b == o.b;
        }
    }
    void solve() throws IOException {
        int n = readInt();

        Pair[] one = new Pair[n];
        Pair[] two = new Pair[n];

        for (int i=0; i<n; ++i) one[i] = new Pair(readInt(), readInt() );
        for (int i=0; i<n; ++i) two[i] = new Pair(readInt() , readInt() );

        int minA = Integer.MAX_VALUE;
        int minB = Integer.MAX_VALUE;

        int maxA = Integer.MIN_VALUE;
        int maxB = Integer.MIN_VALUE;
        for (int i=0; i<n; ++i){
            minA = Math.min(minA, one[i].a);
            minB = Math.min(minB, one[i].b);
            maxA = Math.max(maxA, two[i].a);
            maxB = Math.max(maxB, two[i].b);
        }
